import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import axios from 'axios';
import toast from 'react-hot-toast';
import Avatar from '../components/Avatar';
import './Pairings.css';

export default function PeopleManager({ data, refreshData, API }) {
  const [newName, setNewName] = useState('');
  const [saving, setSaving] = useState(false);
  const people = data?.people || [];

  const addPerson = async () => {
    if (!newName.trim()) return;
    if (people.includes(newName.trim())) { toast.error('Already on the list!'); return; }
    setSaving(true);
    try {
      await axios.put(`${API}/people`, { people: [...people, newName.trim()] });
      toast.success(`${newName.trim()} added to the coffee crew! ☕`);
      setNewName('');
      refreshData();
    } catch (e) {
      toast.error('Failed to add person');
    } finally {
      setSaving(false);
    }
  };

  const removePerson = async (name) => {
    if (!window.confirm(`Remove ${name} from the list?`)) return;
    try {
      await axios.put(`${API}/people`, { people: people.filter(p => p !== name) });
      toast.success(`${name} removed`);
      refreshData();
    } catch (e) {
      toast.error('Failed to remove');
    }
  };

  return (
    <div className="people-page">
      <div className="page-header">
        <h1 className="page-title">🧑‍🤝‍🧑 Team Members</h1>
        <p className="page-subtitle">Manage who's in the coffee chat rotation. Changes apply to future pairings.</p>
      </div>

      {/* Add form */}
      <motion.div
        className="card"
        style={{ marginBottom: 20 }}
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
      >
        <div className="section-label">Add New Member</div>
        <div className="add-person-form">
          <input
            type="text"
            placeholder="Full name (e.g. Jane Smith)..."
            value={newName}
            onChange={e => setNewName(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && addPerson()}
            style={{ fontSize: 14 }}
          />
          <motion.button
            className="btn btn-primary"
            onClick={addPerson}
            disabled={!newName.trim() || saving}
            whileHover={{ scale: 1.04 }}
            whileTap={{ scale: 0.96 }}
          >
            + Add
          </motion.button>
        </div>
      </motion.div>

      {/* People list */}
      <motion.div className="card" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
          <div className="section-label">Current Team</div>
          <span className="badge badge-primary">{people.length} members</span>
        </div>

        <motion.div
          className="people-list"
          initial="hidden"
          animate="visible"
          variants={{ visible: { transition: { staggerChildren: 0.04 } } }}
        >
          <AnimatePresence>
            {people.map((person, i) => (
              <motion.div
                key={person}
                className="person-row"
                variants={{
                  hidden: { opacity: 0, x: -20, scale: 0.95 },
                  visible: { opacity: 1, x: 0, scale: 1 }
                }}
                exit={{ opacity: 0, x: 30, scale: 0.9, transition: { duration: 0.2 } }}
                layout
              >
                <Avatar name={person} size={38} />
                <div className="person-info">
                  <div className="person-name">{person}</div>
                  <div className="person-idx">#{String(i + 1).padStart(2, '0')}</div>
                </div>
                <motion.button
                  onClick={() => removePerson(person)}
                  whileHover={{ scale: 1.2, color: '#EF4444' }}
                  whileTap={{ scale: 0.85 }}
                  style={{
                    background: 'none', border: 'none', cursor: 'pointer',
                    color: 'var(--text-muted)', fontSize: 15, padding: '4px 6px',
                    borderRadius: 6, display: 'flex', alignItems: 'center',
                    transition: 'color 0.2s',
                  }}
                >
                  ✕
                </motion.button>
              </motion.div>
            ))}
          </AnimatePresence>
        </motion.div>
      </motion.div>
    </div>
  );
}
